<?php
namespace App\Http\Controllers;
use App\Models\MembershipLevel;use Illuminate\Http\Request;
class LevelController extends Controller {private function admin(){abort_unless(auth()->user()->role==='admin',403);} public function index(){$this->admin();$levels=MembershipLevel::withCount('members')->orderBy('fee')->get();return view('levels.index',compact('levels'));} public function store(Request $r){$this->admin();$d=$r->validate(['name'=>'required|string|max:100|unique:membership_levels,name','fee'=>'required|numeric|min:0','validity_months'=>'required|integer|min:1|max:120','benefits'=>'nullable|string','description'=>'nullable|string']);MembershipLevel::create($d);return back()->with('success','Level created.');} public function update(Request $r,MembershipLevel $level){$this->admin();$d=$r->validate(['name'=>'required|string|max:100|unique:membership_levels,name,'.$level->id,'fee'=>'required|numeric|min:0','validity_months'=>'required|integer|min:1|max:120','benefits'=>'nullable|string','description'=>'nullable|string','is_active'=>'nullable|boolean']);$level->update($d);return back()->with('success','Level updated.');} public function destroy(MembershipLevel $level){$this->admin();if($level->members()->exists())return back()->with('error','This level is assigned to members. Deactivate it instead.');$level->delete();return back()->with('success','Level deleted.');}}
